interface Command {
  execute(): void;
  undo(): void;
}

class UndoRedoManager {
  private history: Command[] = [];
  private currentIndex: number = -1;

  execute(command: Command): void {
    // Remove any future history when new command is executed
    this.history = this.history.slice(0, this.currentIndex + 1);

    command.execute();
    this.history.push(command);
    this.currentIndex++;
  }

  undo(): boolean {
    if (!this.canUndo) return false;

    this.history[this.currentIndex].undo();
    this.currentIndex--;
    return true;
  }

  redo(): boolean {
    if (!this.canRedo) return false;

    this.currentIndex++;
    this.history[this.currentIndex].execute();
    return true;
  }

  get canUndo(): boolean {
    return this.currentIndex >= 0;
  }

  get canRedo(): boolean {
    return this.currentIndex < this.history.length - 1;
  }

  clear(): void {
    this.history = [];
    this.currentIndex = -1;
  }

  getHistory(): Command[] {
    return [...this.history];
  }

  getCurrentIndex(): number {
    return this.currentIndex;
  }
}

// Example usage with drawing commands
class DrawCommand implements Command {
  constructor(
    private points: Array<{ x: number; y: number }>,
    private context: CanvasRenderingContext2D | null
  ) {}

  execute(): void {
    if (!this.context) return;
    this.context.strokeStyle = '#000';
    this.context.beginPath();
    this.points.forEach((p, i) => {
      if (i === 0) this.context!.moveTo(p.x, p.y);
      else this.context!.lineTo(p.x, p.y);
    });
    this.context.stroke();
  }

  undo(): void {
    if (!this.context) return;
    // In real app, would redraw entire canvas from scratch
    this.context.clearRect(0, 0, this.context.canvas.width, this.context.canvas.height);
  }
}

// Use with React
const [manager] = useState(() => new UndoRedoManager());

const handleAddCommand = (command: Command) => {
  manager.execute(command);
  forceUpdate();
};

const handleUndo = () => {
  if (manager.undo()) forceUpdate();
};

const handleRedo = () => {
  if (manager.redo()) forceUpdate();
};
